      GUI.off('resize', this.delayResize);
      this.delayResize = null;
      this.delayTime   = null;

      this.state.forminputs.forEach(input => {
        clearTimeout(input._xSelectSearchTimer);
        input._xSelectSearchRequest = (input._xSelectSearchRequest || 0) + 1;
